package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringEscapeUtils.escapeJava
 */
public class StringEscapeUtils_escapeJava_TriageGen2Test {

    @Test
    public void testEscapeJava_NullInput() {
        assertNull("Escaping a null string should return null", StringEscapeUtils.escapeJava(null));
    }

    @Test
    public void testEscapeJava_EmptyString() {
        assertEquals("Escaping an empty string should return an empty string", "", StringEscapeUtils.escapeJava(""));
    }

    @Test
    public void testEscapeJava_RegularString() {
        assertEquals("Simple string should remain unchanged", "hello", StringEscapeUtils.escapeJava("hello"));
    }

    @Test
    public void testEscapeJava_SpecialCharacters() {
        // Test common escape sequences
        assertEquals("Newline should be escaped to \\n", "\\n", StringEscapeUtils.escapeJava("\n"));
        assertEquals("Carriage return should be escaped to \\r", "\\r", StringEscapeUtils.escapeJava("\r"));
        assertEquals("Tab should be escaped to \\t", "\\t", StringEscapeUtils.escapeJava("\t"));
        assertEquals("Backspace should be escaped to \\b", "\\b", StringEscapeUtils.escapeJava("\b"));
        assertEquals("Form feed should be escaped to \\f", "\\f", StringEscapeUtils.escapeJava("\f"));
    }

    @Test
    public void testEscapeJava_QuotesAndBackslashes() {
        assertEquals("Double quotes should be escaped", "\\\"", StringEscapeUtils.escapeJava("\""));
        assertEquals("Single quotes should be escaped", "\\'", StringEscapeUtils.escapeJava("'"));
        assertEquals("Backslash should be escaped", "\\\\", StringEscapeUtils.escapeJava("\\"));
    }

    @Test
    public void testEscapeJava_UnicodeCharacters() {
        // Test non-printable or non-ASCII characters using Unicode escapes
        assertEquals("Unicode character should be escaped", "\\u0041", StringEscapeUtils.escapeJava("A")); // Note: 'A' is printable, but testing logic
        // Testing a real non-ASCII char
        assertEquals("Non-ASCII char should be escaped", "\\u03b1", StringEscapeUtils.escapeJava("α"));
    }

    @Test
    public void testEscapeJava_CombinedString() {
        String input = "Line 1\nLine 2\t\"Quote\" \\ Backslash";
        String expected = "Line 1\\nLine 2\\t\\\"Quote\\\" \\\\ Backslash";
        assertEquals("Combined special characters failed", expected, StringEscapeUtils.escapeJava(input));
    }

    @Test
    public void testEscapeJava_ControlCharacters() {
        // Testing low ASCII control characters
        StringBuilder sb = new StringBuilder();
        sb.append((char) 0);
        sb.append((char) 1);
        sb.append((char) 255);

        String escaped = StringEscapeUtils.escapeJava(sb.toString());

        assertTrue("Control character 0 should be escaped", escaped.contains("\\u0000"));
        assertTrue("Control character 1 should be escaped", escaped.contains("\\u0001"));
        assertTrue("Control character 255 should be escaped", escaped.contains("\\u00ff") || escaped.contains("\\u00FF"));
    }
}
